'use strict';

const { Resource } = require('./Resource');

class Airtime extends Resource {
    plans() {
        return this._client.get('products/airtime');
    }

    purchase({ phone, productCode, amount, reference }) {
        return this._client.post('purchases/airtime', {
            phone,
            product_code: productCode,
            amount,
            reference,
        });
    }
}

module.exports = { Airtime };
